import { useState, useEffect } from 'react';

const ModifierGroupe = ({ groupeId }) => {
  const [groupe, setGroupe] = useState(null);
  const [etudiants, setEtudiants] = useState([]);
  const [tuteurs, setTuteurs] = useState([]);
  const [sujets, setSujets] = useState([]);
  const [tuteurId, setTuteurId] = useState('');
  const [sujetId, setSujetId] = useState('');

  useEffect(() => {
    // Récupérer les données du groupe, étudiants, tuteurs et sujets
    fetch(`/api/groupe/${groupeId}`)
      .then((res) => res.json())
      .then((data) => {
        setGroupe(data.groupe);
        setEtudiants(data.etudiants);
        setTuteurId(data.groupe.tuteurId);
        setSujetId(data.groupe.sujetId);
      });

    fetch('/api/tuteurs')
      .then((res) => res.json())
      .then((data) => setTuteurs(data));

    fetch('/api/sujets')
      .then((res) => res.json())
      .then((data) => setSujets(data));
  }, [groupeId]);

  const handleSubmit = async (e) => {
    e.preventDefault();

    // Envoyer les données modifiées au serveur
    const res = await fetch(`/api/groupe/${groupeId}`, {
      method: 'PUT',
      headers: {
        'Content-Type': 'application/json',
      },
      body: JSON.stringify({ tuteurId, sujetId }),
    });

    if (res.ok) {
      alert('Groupe mis à jour avec succès');
    } else {
      alert('Erreur lors de la mise à jour');
    }
  };

  if (!groupe) return <div>Chargement...</div>;

  return (
    <div>
      <h1>Modifier le Groupe : {groupe.nom}</h1>
      <h3>Étudiants :</h3>
      <ul>
        {etudiants.map((etudiant) => (
          <li key={etudiant.id}>{etudiant.nom}</li>
        ))}
      </ul>

      <form onSubmit={handleSubmit}>
        <div>
          <label>Tuteur :</label>
          <select
            value={tuteurId}
            onChange={(e) => setTuteurId(e.target.value)}
          >
            {tuteurs.map((tuteur) => (
              <option key={tuteur.id} value={tuteur.id}>
                {tuteur.nom}
              </option>
            ))}
          </select>
        </div>

        <div>
          <label>Sujet :</label>
          <select
            value={sujetId}
            onChange={(e) => setSujetId(e.target.value)}
          >
            {sujets.map((sujet) => (
              <option key={sujet.id} value={sujet.id}>
                {sujet.nom}
              </option>
            ))}
          </select>
        </div>

        <button type="submit">Mettre à jour</button>
      </form>
    </div>
  );
};

export default ModifierGroupe;
